                    $responsiveValue = fn (string $key, mixed $fallback) => $sectionResponsive['mobile'][$key] ?? $sectionResponsive['tablet'][$key] ?? $sectionResponsive['desktop'][$key] ?? $fallback;
                    $tabletValue = fn (string $key, mixed $fallback) => $sectionResponsive['tablet'][$key] ?? $sectionResponsive['desktop'][$key] ?? $fallback;
                    $spacing = fn (mixed $value) => is_array($value) ? implode(' ', array_map(fn (string $side) => ($value[$side] ?? '') !== '' ? $value[$side] : '0', ['top', 'right', 'bottom', 'left'])) : match((string) $value) { 'compact' => '16px', 'spacious' => '40px', default => '24px' };
                    $padding = fn (mixed $value) => is_array($value) ? implode(' ', array_map(fn (string $side) => ($value[$side] ?? '') !== '' ? $value[$side] : '0', ['top', 'right', 'bottom', 'left'])) : match((string) $value) { 'compact' => '28px', 'spacious' => '72px', default => '48px' };
                    $box = fn (mixed $value, string $kind) => is_array($value) ? implode(' ', array_map(fn (string $side) => ($value[$side] ?? '') !== '' ? $value[$side] : '0', ['top', 'right', 'bottom', 'left'])) : ($kind === 'padding' ? $padding((string) $value) : (($value ?? 'none') === 'none' ? '0' : $spacing((string) $value)));
                    $mobilePadding = fn (mixed $value) => is_array($value) ? implode(' ', array_map(fn (string $side) => ($value[$side] ?? '') !== '' ? $value[$side] : '0', ['top', 'right', 'bottom', 'left'])) : match((string) $value) { 'compact' => '16px', 'spacious' => '36px 24px', default => '24px' };
                    $themeSurface = fn (mixed $value) => match($value) { 'canvas' => 'var(--canvas)', 'surface' => 'var(--surface)', 'surface_muted' => 'var(--surface-muted)', 'action' => 'var(--action)', 'brand' => 'var(--brand)', default => preg_match('/^#[0-9a-fA-F]{6}$/', (string) $value) ? $value : 'transparent' };
                    $themeColor = fn (mixed $value) => preg_match('/^(?:#[0-9a-fA-F]{6}|var\(--[a-z-]+\))$/', (string) $value) ? $value : 'transparent';
                    $overlayColor = function (array $settings): string {
                        if (preg_match('/^#([0-9a-fA-F]{6})$/', (string) ($settings['overlay_color'] ?? ''), $match)) {
                            $opacity = min(100, max(0, (int) ($settings['overlay_opacity'] ?? 35))) / 100;
                            $alpha = $opacity === 0.0 ? '0' : rtrim(rtrim(number_format($opacity, 2, '.', ''), '0'), '.');
                            return sprintf('rgb(%d %d %d / %s)', hexdec(substr($match[1], 0, 2)), hexdec(substr($match[1], 2, 2)), hexdec(substr($match[1], 4, 2)), $alpha);
                        }
                        return match($settings['background_overlay'] ?? 'none') { 'soft' => 'rgb(0 0 0 / 18%)', 'strong' => 'rgb(0 0 0 / 42%)', default => 'transparent' };
                    };
                    $scopedCss = function (string $id, mixed $css): string {
                        $css = trim(str_ireplace(['</style>', '<script'], '', (string) $css));
                        if ($css === '') return '';
