                        'overlay' => $overlayColor($settings),
                        'border-width' => $settings['border_width'] ?? match($settings['border'] ?? 'none') { 'subtle' => '1px', 'strong' => '2px', default => '0px' },
                        'border-style' => $settings['border_style'] ?? (($settings['border'] ?? 'none') === 'none' ? 'none' : 'solid'),
                        'border-color' => $themeColor($settings['border_color'] ?? (($settings['border'] ?? 'none') === 'strong' ? 'var(--line-strong)' : 'var(--line)')),
                        'radius' => isset($settings['radius_top_left'], $settings['radius_top_right'], $settings['radius_bottom_right'], $settings['radius_bottom_left']) ? implode(' ', [$settings['radius_top_left'], $settings['radius_top_right'], $settings['radius_bottom_right'], $settings['radius_bottom_left']]) : match($settings['radius'] ?? 'none') { 'small' => '8px', 'medium' => '16px', 'large' => '24px', default => '0px' },
